import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..'), isolated = path.join(root, '.work/r32');
const checkpointPath = path.join(root, '.work/rrsi-source-directory-source-checkpoint.json'), checkpoint = JSON.parse(fs.readFileSync(checkpointPath));
const sha = file => createHash('sha256').update(fs.readFileSync(file)).digest('hex');
for (const entry of checkpoint.sourceDigests) assert.equal(sha(path.join(isolated, entry.path)), entry.sha256, entry.path);
const { openJournalBoundaryFixture } = await import(pathToFileURL(path.join(isolated, 'packages/cli/__tests__/fixtures/evolution-journal-boundary.js')));
const { captureEvolutionLedgerDirectoryBoundary: capture } = await import(pathToFileURL(path.join(isolated, 'packages/cli/src/lib/evolution/evolution-ledger.js')));
const { rrsiHash } = await import(pathToFileURL(path.join(isolated, 'packages/cli/src/lib/evolution/rrsi-data.js')));
const digest = descriptor => rrsiHash('chainlesschain.rrsi-source-journal-directory-boundary/v1', descriptor);
const temp = fs.realpathSync.native(os.tmpdir()), temporary = fs.mkdtempSync(path.join(temp, 'cc-source-directory-posix-'));
const results = [];
const unsafe = operation => assert.throws(operation, error => error.code === 'CC_EVOLUTION_LEDGER_STORE_UNSAFE');
const markerFields = file => {
  const stat = fs.lstatSync(file);
  return Object.fromEntries(['dev','ino','size','nlink','mode','mtimeMs','ctimeMs','birthtimeMs'].map(field => [field, String(stat[field])]));
};
let legacyMarkerDiagnostic = null;
try {
  const fixture = openJournalBoundaryFixture(temporary), boundary = capture(fixture.ledger), originalDigest = digest(boundary.descriptor);
  fixture.arm(fixture.files.head);
  assert.equal(boundary.recheck(), boundary.descriptor);
  assert.equal(fixture.io.allOpens.length, 0); assert.equal(fixture.io.live.size, 0);
  for (const entry of boundary.descriptor.directories) {
    const stat = fs.lstatSync(entry.path, { bigint: true });
    for (const field of ['dev', 'ino', 'mode', 'uid', 'gid']) assert.equal(entry.identity[field], String(stat[field]));
  }
  results.push({ scenario: 'stable-metadata-only', passed: true, exactFieldsMatched: true, opens: 0, liveDescriptors: 0 });
  fixture.io.armed = false;
  fixture.append('posix-directory-append'); fixture.ledger.checkpointState();
  assert.equal(digest(capture(fixture.open()).descriptor), originalDigest);
  assert.equal(digest(boundary.recheck()), originalDigest);
  results.push({ scenario: 'append-snapshot-and-original-directory-reopen', passed: true, digestUnchanged: true });
  const markerBefore = markerFields(fixture.ledger.storeMarkerPath);
  for (const mode of ['clone', 'missing', 'symlink', 'fifo']) for (const entry of boundary.descriptor.directories) {
    const saved = path.join(temporary, `saved-${mode}-${entry.role}`);
    assert.ok(entry.path.startsWith(temporary + path.sep)); assert.equal(path.dirname(saved), temporary);
    const originalInode = fs.lstatSync(entry.path, { bigint: true }).ino;
    fixture.arm(fixture.files.head);
    fs.renameSync(entry.path, saved);
    let actualFifo = false;
    try {
      if (mode === 'clone') fs.cpSync(saved, entry.path, { recursive: true });
      if (mode === 'symlink') fs.symlinkSync(saved, entry.path, 'dir');
      if (mode === 'fifo') {
        const child = spawnSync('mkfifo', [entry.path], { encoding: 'utf8', timeout: 1000 });
        assert.equal(child.status, 0, child.stderr); actualFifo = fs.lstatSync(entry.path).isFIFO(); assert.equal(actualFifo, true);
      }
      unsafe(() => capture(fixture.ledger)); unsafe(() => boundary.recheck());
      assert.equal(fixture.io.allOpens.length, 0); assert.equal(fixture.io.live.size, 0);
      if (mode === 'missing') assert.equal(fs.existsSync(entry.path), false);
      results.push({ scenario: `${mode}/${entry.role}`, passed: true, opens: 0, liveDescriptors: 0,
        missingNotRecreated: mode === 'missing', actualFifo });
    } finally {
      fixture.io.armed = false;
      if (mode === 'clone') fs.rmSync(entry.path, { recursive: true, force: true });
      else if (mode !== 'missing') fs.unlinkSync(entry.path);
      fs.renameSync(saved, entry.path);
    }
    assert.equal(fs.lstatSync(entry.path, { bigint: true }).ino, originalInode);
    assert.equal(digest(boundary.recheck()), originalDigest);
  }
  fs.chmodSync(fixture.ledger.rootDir, 0o710);
  try { unsafe(() => boundary.recheck()); } finally { fs.chmodSync(fixture.ledger.rootDir, 0o700); }
  assert.equal(digest(boundary.recheck()), originalDigest);
  results.push({ scenario: 'actual-directory-mode-change', passed: true, originalModeRestored: true });
  const markerAfter = markerFields(fixture.ledger.storeMarkerPath);
  try { fixture.ledger.verify(); legacyMarkerDiagnostic = { valid: true, markerBefore, markerAfter }; }
  catch (error) {
    assert.equal(error.code, 'CC_EVOLUTION_LEDGER_CORRUPT');
    assert.match(error.message, /store incarnation marker file instance was replaced or replayed/);
    legacyMarkerDiagnostic = { valid: false, code: error.code, message: error.message, markerBefore, markerAfter,
      scope: 'Existing signed legacy Number marker fence after actual directory rename/copy controls, not a directory-capability success or full history recovery claim' };
  }
  // The leaf scope control needs a fresh healthy store; the metadata-only
  // capability deliberately does not authenticate the legacy marker instance.
  const scopeFixture = openJournalBoundaryFixture(path.join(temporary, 'fresh-leaf-scope'));
  const scopeBoundary = capture(scopeFixture.ledger), scopeDigest = digest(scopeBoundary.descriptor);
  assert.equal(scopeFixture.ledger.verify().sequence, 1);
  const originalHead = fs.readFileSync(scopeFixture.files.head);
  fs.writeFileSync(scopeFixture.files.head, 'corrupt');
  try {
    assert.equal(digest(scopeBoundary.recheck()), scopeDigest);
    assert.equal(scopeBoundary.descriptor.journalContentsVerified, false);
    assert.throws(() => scopeFixture.ledger.verify(), error => error.code === 'CC_EVOLUTION_LEDGER_CORRUPT' && error.message.includes('ledger HEAD'));
  } finally { fs.writeFileSync(scopeFixture.files.head, originalHead); }
  assert.deepEqual(fs.readFileSync(scopeFixture.files.head), originalHead);
  assert.equal(scopeFixture.ledger.verify().sequence, 1);
  results.push({ scenario: 'metadata-only-is-not-HEAD-content-authentication', passed: true, originalBytesRestored: true });
  const helpers = await import(pathToFileURL(path.join(isolated, 'packages/cli/__tests__/fixtures/rrsi-observed-text.js')));
  const backendModule = await import(pathToFileURL(path.join(isolated, 'packages/cli/src/lib/evolution/evolution-ledger-file-backend.js')));
  const historyModule = await import(pathToFileURL(path.join(isolated, 'packages/cli/src/lib/evolution/rrsi-tenant-index-anchor-history.js')));
  const rrsi = helpers.openObservedTextFixture(path.join(temporary, 'rrsi'));
  const index = helpers.openObservedTextIndex(rrsi);
  const source = backendModule.captureEvolutionLedgerFileBackendSourceDirectoryBoundary(rrsi.store.backend);
  const history = historyModule.inspectRrsiTenantIndexHistory({ observedTextIndex: index });
  assert.equal(history.sourceJournalDirectoryBoundaryDigest, digest(source.descriptor));
  assert.equal(history.sourceJournalBoundaryScope, 'source-journal-four-directories');
  assert.equal(history.fullPhysicalStorageGraphVerified, false); assert.equal(history.decision, 'HOLD');
  results.push({ scenario: 'genuine-v2-private-source-and-retained-history', passed: true, sourceDigestMatched: true, decision: 'HOLD' });
} finally {
  assert.equal(path.dirname(temporary), temp); assert.ok(path.basename(temporary).startsWith('cc-source-directory-posix-'));
  fs.rmSync(temporary, { recursive: true, force: true });
}
for (const entry of checkpoint.sourceDigests) assert.equal(sha(path.join(isolated, entry.path)), entry.sha256, entry.path);
assert.equal(results.length, 21);
const out = { recordedAt: new Date().toISOString(), platform: process.platform, nodeVersion: process.version,
  kernel: os.release(), passedScenarios: results.length, failures: 0, sourceCheckpointSha256: sha(checkpointPath),
  sourceDigests: checkpoint.sourceDigests, runnerSha256: sha(fileURLToPath(import.meta.url)), results, legacyMarkerDiagnostic,
  fullPhysicalStorageGraphVerified: false, productionAuthority: false };
fs.writeFileSync(path.join(root, '.work/rrsi-source-directory-posix.json'), JSON.stringify(out, null, 2) + '\n');
process.stdout.write(JSON.stringify({ passedScenarios: results.length, failures: 0 }) + '\n');

