import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';
const root = 'C:/code/chainlesschain', isolated = `${root}/.work/r32`;
const file = 'packages/cli/src/lib/evolution/rrsi-observed-text-index.js';
const original = fs.readFileSync(path.join(root, file));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const runnerSha256 = sha(fs.readFileSync(fileURLToPath(import.meta.url)));
const baseline = JSON.parse(fs.readFileSync(`${root}/.work/rrsi-source-directory-baseline.json`));
assert.equal(sha(original), baseline.rootBeforePropagation.find(entry => entry.path === file).sha256);
const legacy = `${isolated}/packages/cli/src/lib/evolution/rrsi-source-directory-legacy-observed-test-only.js`;
assert.ok(!fs.existsSync(legacy)); fs.writeFileSync(legacy, original, { flag: 'wx' });
const temp = fs.realpathSync.native(os.tmpdir()), directory = fs.mkdtempSync(path.join(temp, 'cc-source-directory-upgrade-'));
function inventory(target) {
  const entries = [];
  const walk = dir => { for (const name of fs.readdirSync(dir).sort()) {
    const child = path.join(dir, name), stat = fs.lstatSync(child);
    if (stat.isDirectory()) walk(child);
    else { assert.equal(stat.isFile(), true); entries.push({ path: path.relative(target, child), sha256: sha(fs.readFileSync(child)) }); }
  } };
  walk(target); return entries;
}
try {
  const old = await import(pathToFileURL(legacy));
  const current = await import(pathToFileURL(path.join(isolated, file)));
  const helpers = await import(pathToFileURL(`${isolated}/packages/cli/__tests__/fixtures/rrsi-observed-text.js`));
  const fixture = helpers.openObservedTextFixture(directory);
  const first = old.createRrsiObservedTextIndex(fixture.composition);
  helpers.registerPreparationPlan(fixture); helpers.reservePreparation(fixture);
  const observed = first.registerObservedSkillText(helpers.observationRequest(fixture, '# Old observed record\r\n'));
  const originalDescriptor = first.descriptor;
  const oldSnapshot = old.captureRrsiObservedTextIndex(first).captureHistoryCheckpoints({ checkpoints: [] }).snapshot;
  const artifactFiles = path.join(directory, 'store/artifacts/files'), originalFiles = inventory(artifactFiles);
  const originalIndex = fs.readFileSync(path.join(directory, 'store/artifacts/index.jsonl'));
  const next = current.createRrsiObservedTextIndex(fixture.composition);
  const newSnapshot = current.captureRrsiObservedTextIndex(next).captureHistoryCheckpoints({ checkpoints: [] }).snapshot;
  assert.deepEqual(next.descriptor, originalDescriptor);
  assert.equal(newSnapshot.localCompositionDigest, oldSnapshot.localCompositionDigest);
  assert.deepEqual(newSnapshot.current, oldSnapshot.current);
  assert.equal(typeof newSnapshot.sourceJournalDirectoryBoundaryDigest, 'string');
  assert.equal(oldSnapshot.sourceJournalDirectoryBoundaryDigest, undefined);
  assert.deepEqual(inventory(artifactFiles), originalFiles);
  assert.deepEqual(fs.readFileSync(path.join(directory, 'store/artifacts/index.jsonl')), originalIndex);
  assert.deepEqual(next.readObservedText(observed.skillTextDigest), first.readObservedText(observed.skillTextDigest));
  const second = next.registerObservedSkillText(helpers.observationRequest(fixture, '# New observed record\r\n'));
  const reverse = old.createRrsiObservedTextIndex(fixture.composition);
  assert.deepEqual(reverse.descriptor, originalDescriptor);
  assert.deepEqual(reverse.readObservedText(second.skillTextDigest), next.readObservedText(second.skillTextDigest));
  assert.deepEqual(reverse.readObservedText(observed.skillTextDigest), first.readObservedText(observed.skillTextDigest));
  const reverseSnapshot = old.captureRrsiObservedTextIndex(reverse).captureHistoryCheckpoints({ checkpoints: [] }).snapshot;
  const finalSnapshot = current.captureRrsiObservedTextIndex(next).captureHistoryCheckpoints({ checkpoints: [] }).snapshot;
  assert.equal(reverseSnapshot.localCompositionDigest, oldSnapshot.localCompositionDigest);
  assert.equal(finalSnapshot.localCompositionDigest, oldSnapshot.localCompositionDigest);
  assert.equal(finalSnapshot.sourceJournalDirectoryBoundaryDigest, newSnapshot.sourceJournalDirectoryBoundaryDigest);
  const after = new Map(inventory(artifactFiles).map(entry => [entry.path, entry.sha256]));
  for (const entry of originalFiles) assert.equal(after.get(entry.path), entry.sha256);
  const out = { recordedAt: new Date().toISOString(), platform: process.platform, nodeVersion: process.version,
    runnerSha256, roundtripCompositionAndSourceDigestUnchanged: true,
    originalObservedSourceSha256: sha(original), upgradedObservedSourceSha256: sha(fs.readFileSync(path.join(isolated, file))),
    procedure: 'Old section-35 observed-index module writes real retained text through current actual v2 fixture; new module opens the same original composition and reads old records, writes another record; old module reopens and reads both generations. Current ledger/file-backend assembly is shared; this checks observed persistent-record compatibility, not a complete deployment upgrade',
    sameOriginalDirectories: true, oldPersistentDescriptorUnchanged: true, oldLocalCompositionDigestUnchanged: true,
    oldSnapshotHasNoNewSourceField: true, newSnapshotHasSourceDirectoryDigest: true,
    originalArtifactFileCount: originalFiles.length, originalArtifactFileHashes: originalFiles,
    artifactIndexBytesUnchangedDuringNewReadback: true, allOriginalArtifactFilesUnchangedAfterRoundtrip: true,
    oldRecordsReadByNewSource: true, newRecordsReadByOldSource: true,
    sourceJournalDirectoryBoundaryDigest: newSnapshot.sourceJournalDirectoryBoundaryDigest,
    fullPhysicalStorageGraphVerified: false, productionAuthority: false,
  };
  fs.writeFileSync(`${root}/.work/rrsi-source-directory-legacy.json`, JSON.stringify(out, null, 2) + '\n');
  console.log(JSON.stringify({ oldWritesNewReads: true, newWritesOldReads: true, persistentDescriptorUnchanged: true, originalArtifactFiles: originalFiles.length }));
} finally {
  assert.equal(path.dirname(directory), temp); assert.ok(path.basename(directory).startsWith('cc-source-directory-upgrade-'));
  fs.rmSync(directory, { recursive: true, force: true });
  fs.rmSync(legacy, { force: true });
}
